test('onIdle waits for running and queued jobs', async t => {
	const limit = pLimit(1);
	const completed = [];

	const first = limit(async () => {
		await delay(50);
		completed.push('first');
	});
	const second = limit(async () => {
		await delay(10);
		completed.push('second');
	});

	let idle = false;
	const markIdle = async () => {
		await limit.onIdle();
		idle = true;
	};

	const idlePromise = markIdle();

	t.false(idle);
	await idlePromise;
	t.true(idle);
	t.deepEqual(completed, ['first', 'second']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await Promise.all([first, second]);
});

test('onIdle supports multiple concurrent waiters', async t => {
	const limit = pLimit(1);

	limit(() => delay(30));

	const results = [];
	const waiters = Array.from({length: 5}, (_, index) => (async () => {
		await limit.onIdle();
		results.push(index);
	})());

	await Promise.all(waiters);
	t.deepEqual(results, [0, 1, 2, 3, 4]);
});

test('onIdle resolves after a rejected job settles', async t => {
	const limit = pLimit(1);
	const error = new Error('🦄');

	const rejected = limit(async () => {
		await delay(20);
		throw error;
	});

	const idlePromise = limit.onIdle();

	await t.throwsAsync(rejected, {is: error});
	await t.notThrowsAsync(idlePromise);
	t.is(limit.activeCount, 0);
});

test('onIdle does not resolve while a job enqueues another job on resolution', async t => {
	const limit = pLimit(1);
	const order = [];

	const outer = limit(async () => {
		await delay(20);
		order.push('outer');
		// Enqueue a new job before the outer job settles.
		limit(async () => {
			await delay(20);
			order.push('inner');
		});
	});

	let idle = false;
	const markIdle = async () => {
		await limit.onIdle();
		idle = true;
	};

	const idlePromise = markIdle();

	// Give the idle check a chance to (incorrectly) fire early.
	await delay(30);
	t.false(idle);
	t.is(limit.activeCount, 1);

	await idlePromise;
	t.true(idle);
	t.deepEqual(order, ['outer', 'inner']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await outer;
});

test('onIdle counts reserved slots as active', async t => {
	const limit = pLimit(2);

	const runningPromise = limit(() => delay(40));
	const reservedPromise = limit(() => delay(40));

	t.is(limit.activeCount, 2);

	let idle = false;
	const markIdle = async () => {
		await limit.onIdle();
		idle = true;
	};

	const idlePromise = markIdle();

	await delay(10);
	t.false(idle);

	await idlePromise;
	t.true(idle);

	await Promise.all([runningPromise, reservedPromise]);
});

test('clearQueue releases onIdle waiters when queue is empty and no jobs are active (rejectOnClear: false)', async t => {
	const limit = pLimit(1);

	const runningPromise = limit(() => delay(20));
	const discarded = limit(() => delay(1000));
	const discardedToo = limit(() => delay(1000));

	await Promise.resolve();
	t.is(limit.pendingCount, 2);

	const idlePromise = limit.onIdle();

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(idlePromise);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await runningPromise;

	// The discarded promises intentionally stay unresolved under rejectOnClear: false.
	// They are still pending promises, not settled ones.
	t.true(discarded instanceof Promise);
	t.true(discardedToo instanceof Promise);
});

test('clearQueue releases onIdle waiters when there are no active jobs (rejectOnClear: false)', async t => {
	const limit = pLimit(2);

	// Fill the reserved/running slots.
	const runningOne = limit(() => delay(30));
	const runningTwo = limit(() => delay(30));
	limit(() => delay(1000));

	await Promise.resolve();
	t.is(limit.pendingCount, 1);

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(limit.onIdle());
	t.is(limit.activeCount, 0);

	await Promise.all([runningOne, runningTwo]);
});

