test('onIdle preserves FIFO ordering and concurrency changes', async t => {
	const limit = pLimit(1);
	const order = [];

	const promises = Array.from({length: 6}, (_, index) => limit(async () => {
		order.push(index);
		await delay(5);
	}));

	// Increase concurrency while jobs are queued; FIFO order must hold.
	limit.concurrency = 3;

	const idlePromise = limit.onIdle();
	await Promise.all([...promises, idlePromise]);

	t.deepEqual(order, [0, 1, 2, 3, 4, 5]);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

