	await delay(30);
	t.false(idle);
	t.is(limit.activeCount, 1);

	await idlePromise;
	t.true(idle);
	t.deepEqual(order, ['outer', 'inner']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await outer;
});

